1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	
4	const BASE_PREMIUMS: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	};
9	
10	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
11	// floating-point error that shifts the spec's round-up in MHPCO's favour.
12	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
13	
14	export type ScenarioResult = { premium: number };
15	
16	type Item = { type: string };
17	
18	type Scenario = {
19	  steps: { items: Item[] }[];
20	};
21	
22	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
23	  const items = scenario.steps[0].items;
24	  const basePremium = items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0);
25	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, basePremium);
26	  const premium = Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
27	  return { results: [{ premium }] };
28	};
29

