75	  // --- Policy-wide modifiers ---
76	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount on the policy base premium");
77	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
78	  it.todo("first insurance surcharge of 10 % applies to every quote's items");
79	  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");
