95	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
96	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
97	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
98	
99	  // --- Claim: deductible per damage event ---
