101	
102	  // --- Claim: cap ---
103	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
104	  it.todo("a cursed sword → cap 2000 G based on the unmodified insurance value");
105	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)");
106	  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
107	  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");
108	
